def iscube(a):
    import math
    if a == 0:
        return True
    # Take absolute value, then integer cube root
    x = int(abs(a) ** (1/3))
    # Check both x and x+1 due to floating point inaccuracies
    for candidate in (x - 1, x, x + 1):
        if candidate < 0:
            continue
        if candidate ** 3 == abs(a):
            return True
    return False
```

