def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = [p for p in range(2, a + 1) if is_prime(p)]
    count = 0
    for p1 in primes:
        if p1 * p1 > a:
            break
        for p2 in primes:
            if p2 * p2 > a // p1:
                break
            prod = p1 * p2
            if prod * prod > a:
                break
            for p3 in primes:
                if p3 * p3 > a // prod:
                    break
                prod *= p3
                if prod == a and count == 1:
                    return True
                count += 1
    return False
```

