def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    count = 0
    for i in range(2, int(a**0.5) + 1):
        if not is_prime(i):
            continue
        for j in range(i, int(a**0.5) + 1):
            if not is_prime(j):
                continue
            for k in range(j, a // (i * j) + 1):
                if not is_prime(k):
                    continue
                if i * j * k == a:
                    count += 1
                    break
            if count > 0:
                break
        if count > 0:
            break

    return count == 1
