def is_multiply_prime(a):
    """Write a function that returns True if the given number is the product of exactly 3 prime numbers
    and False otherwise.
    Knowing that a is less than 100.

    Example:
    is_multiply_prime(30) == True  # because 30 = 2 * 3 * 5
    """
    # Precompute primes up to 100
    primes = []
    if a >= 2:
        for i in range(2, a + 1):
            is_prime = True
            for p in primes:
                if p * p > i:
                    break
                if i % p == 0:
                    is_prime = False
                    break
            if is_prime:
                primes.append(i)

    # Check all combinations of 3 primes (with replacement) whose product equals a
    count = 0
    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                prod = primes[i] * primes[j] * primes[k]
                if prod == a:
                    count += 1
                if count > 1:
                    break
            if count > 1:
                break
        if count > 1:
            break

    return count == 1
```

