def recursive_list_sum(lst):
    """Recursively flatten a nested list and return the sum of all numeric elements."""
    if not isinstance(lst, list):
        return lst if isinstance(lst, (int, float)) else 0

    total = 0
    for item in lst:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        elif isinstance(item, (int, float)):
            total += item
        else:
            continue  # ignore non-numeric elements

    return total
