def sum(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def get_divisors(n):
        divs = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
        return divs

    common = get_divisors(gcd(a, b))
    return sum(common)
```

