def is_multiply_prime(a):
    """Returns True if the given number is the product of exactly 3 prime numbers, False otherwise.
    Note: The problem statement implies that the three primes must be distinct (as shown by 30 = 2 * 3 * 5).
    If the requirement were to allow repeated primes (e.g., 8 = 2 * 2 * 2), the logic would differ.
    Based on the example provided (30 = 2 * 3 * 5), we assume distinct primes are required.
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Precompute primes up to 'a' for efficiency, though 'a' is small (< 100)
    primes = [p for p in range(2, a + 1) if is_prime(p)]

    # Iterate through combinations of 3 distinct primes (p1, p2, p3) such that p1 < p2 < p3
    # and p1 * p2 * p3 == a
    for i in range(len(primes)):
        p1 = primes[i]
        if p1 * p1 * p1 > a:  # Optimization: if smallest prime cubed exceeds a, no need to continue
            break
        for j in range(i + 1, len(primes)):
            p2 = primes[j]
            if p1 * p2 * p2 > a:
                break
            for k in range(j + 1, len(primes)):
                p3 = primes[k]
                if p1 * p2 * p3 == a:
                    return True
                elif p1 * p2 * p3 > a:
                    break
    return False
```

