def intersection_array(arr1: list, arr2: list) -> list:
    """Return the intersection of two arrays, with each element appearing
    as many times as it appears in both arrays (minimum of counts in both)."""
    if not arr1 or not arr2:
        return []

    count1 = {}
    for item in arr1:
        count1[item] = count1.get(item, 0) + 1

    result = []
    for item in arr2:
        if item in count1 and count1[item] > 0:
            result.append(item)
            count1[item] -= 1

    return result
```

