def sort_array(arr):
    """
    Sort an array of non-negative integers according to the number of ones in
    their binary representation (ascending), and for ties, by decimal value (ascending).
    Handles negative numbers by sorting them after all non-negative ones, primarily by
    the count of set bits in their two's complement representation, then by value.
    """
    def count_bits(n):
        # For non-negative, bin(n).count('1')
        # For negative, use two's complement bit count (same as bin(n & mask).count('1') where mask is all 1s)
        # Python's bin() for negative gives "-0b..." so we strip the '-' and count '1's
        if n >= 0:
            return bin(n).count('1')
        else:
            # For negative numbers, we treat them as having a count equal to the number of 1s in their binary representation
            # In two's complement, the number of 1s for -n is total_bits - bin(n).count('1') where n is positive
            # But simpler: just count '1' in bin(n) after removing the minus sign
            return bin(n).count('1')

    return sorted(arr, key=lambda x: (count_bits(x), x))
