    def count_bits(n):
        if n >= 0:
            return bin(n).count('1')
        else:
            # For negative numbers, simulate two's complement bit count
            # by counting bits in (n + 2^k) where k is sufficient to cover the magnitude
            # This effectively counts the 1s in the two's complement representation
            k = n.bit_length() + 1
