def sort_array(arr):
    """
    Sort an array of integers according to the number of ones in their binary representation (ascending),
    and for ties, by decimal value (ascending).

    For non-negative numbers: count = bin(n).count('1')
    For negative numbers: count = bin(n).count('-' + bin(n)) - 1  (total minus the leading '-').
    """
    def count_bits(n):
        if n >= 0:
            return bin(n).count('1')
        else:
            bin_str = bin(n)
            if bin_str.startswith('-'):
                return bin_str[1:].count('1')
            return bin_str.count('1')

    return sorted(arr, key=lambda x: (count_bits(x), x))
