def is_multiply_prime(a):
    def count_prime_factors(n):
        if n <= 1:
            return 0
        count = 0
        d = 2
        while d * d <= n:
            while n % d == 0:
                count += 1
                n //= d
            d += 1
        if n > 1:
            count += 1
        return count

    return count_prime_factors(a) == 3
