def sort_array(arr):
    """
    Sort an array of integers according to the number of ones in their binary representation (ascending),
    and for ties, by decimal value (ascending).
    """
    def bit_count(n):
        # Remove the sign bit for negative numbers to count only magnitude bits
        if n < 0:
            mask = ~n
            mask = mask & (~0x7FFFFFFFFFFFFFFF)
        else:
            mask = 0
        return bin(mask & (mask >> 1) | mask).count('1')

    return sorted(arr, key=lambda x: (bit_count(x), x))
```

