def sort_array(arr):
    """
    Sort an array of integers according to the number of ones in their binary representation (ascending),
    and for ties, by decimal value (ascending).
    """
    def bit_count(n):
        # Handle negative numbers by using two's complement representation logic
        # or simply count bits in the absolute value and adjust for sign
        # Python's bin(n) includes a '-' prefix for negatives, so we can count '1's directly
        if n < 0:
            # For negative numbers, we treat them as if they were in two's complement
            # but the problem examples suggest we just count the '1's in the binary string
            # e.g., bin(-5) -> '-101', count('1') -> 1, which matches the expected behavior
            return bin(n).count('1')
        else:
            return bin(n).count('1')

    return sorted(arr, key=lambda x: (bit_count(x), x))
```

