def recursive_list_sum(lst):
    """Recursively sum all numeric elements in a nested list structure.

    Handles:
    - Lists (recursively flattened)
    - Integers/floats (added)
    - Non-numeric values (ignored)
    """
    total = 0

    def is_numeric(value):
        """Check if value is a supported numeric type."""
        return isinstance(value, (int, float, complex))

    def flatten_and_sum(item):
        """Recursively process a single item and return its sum."""
        if isinstance(item, list):
            # Recursively process each element in the list
            for sub_item in item:
                if is_numeric(sub_item):
                    total += sub_item
                else:
                    # Handle nested lists by calling flatten_and_sum recursively
                    total += flatten_and_sum(sub_item)
        elif is_numeric(item):
            total += item

    # Process the input list
    if isinstance(lst, list):
        for item in lst:
            if is_numeric(item):
                total += item
            else:
                total += flatten_and_sum(item)

    return total
```

