def sum(a: int, b: int) -> int:
    """
    Return the sum of all common divisors of two positive integers a and b.
    A common divisor is a positive integer that divides both a and b without remainder.
    """
    if a <= 0 or b <= 0:
        raise ValueError("Both numbers must be positive integers.")

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)

    total = 0
    d = 1
    while d * d <= g:
        if g % d == 0:
            total += d
            if d * d != g:
                total += g // d
        d += 1

    return total
```

